-- Remove provider-usage rows generated by the old seeded demo/system accounts.
-- This is deliberately scoped to known fixture identities; real customer telemetry is preserved.
DELETE FROM public.provider_usage_events
WHERE user_id IN ('usr-demo-001', 'usr-admin-001')
   OR lower(coalesce(user_email, '')) IN ('demo@bizmate.ai', 'admin@bizmate.ai');
